"""Self-contained review UI; model outputs remain read-only."""

TEMPLATE = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CoreOrigin · BlindSpot review</title>
<style>body{background:#0a1220;color:#e6edf7;font:16px system-ui;margin:0}main{max-width:1250px;margin:auto;padding:28px}section{background:#142238;border:1px solid #2b4362;border-radius:14px;padding:22px;margin:18px 0}h1{font-size:36px;margin:8px 0}p{color:#b3c4da;line-height:1.5}button,select{background:#254b6b;color:white;border:1px solid #48667e;border-radius:7px;padding:10px;margin:4px}button:disabled{opacity:.4}video{width:100%;background:black}canvas{width:100%;background:#143d39}textarea{box-sizing:border-box;width:100%;min-height:100px;background:#0a1728;color:white;padding:10px}.grid{display:grid;grid-template-columns:1.4fr 1fr;gap:18px}@media(max-width:800px){.grid{grid-template-columns:1fr}}.badge{color:#73dfc0}input[type=range]{width:100%}label{display:block;margin-top:12px}code{overflow-wrap:anywhere}.state{font-size:22px;font-weight:650}</style>
<main><div class="badge">CoreOrigin · BlindSpot · private review</div><h1 id="title"></h1><p id="notice"></p><p id="identity"></p>
<section><label for="query">Review moment</label><select id="query"></select><button id="prev">Previous moment</button><button id="next">Next moment</button><p id="reason"></p>
<div class="grid"><div><video id="video" controls preload="metadata"></video><p id="videoStatus" role="status"></p></div><div><canvas id="pitch" width="632" height="408" aria-label="Sampled pitch positions"></canvas><p id="detail"></p><p>Blue = home · violet = away · yellow = observed ball. Slots are not persistent player identities. Missing ball positions are hidden.</p></div></div>
<label for="frame">Tactical video frame</label><input id="frame" type="range" step="1"><button id="backFrame">−1 frame</button><button id="forwardFrame">+1 frame</button><p id="prediction" class="state"></p></section>
<section><h2>Evidence notes</h2><p>Notes are saved automatically in this browser for this candidate. Export them for a portable copy. Notes never modify the algorithmic CSV; interaction time does not measure proven time saved.</p><label for="state">Review outcome</label><select id="state"><option value="unresolved">Unresolved</option><option value="H">Home possession</option><option value="A">Away possession</option><option value="D">Dead ball</option><option value="insufficient">Insufficient evidence</option></select><label for="notes">Evidence and uncertainty</label><textarea id="notes" maxlength="4000" placeholder="Observed evidence, ambiguous timing, tracking issues…"></textarea><button id="save">Save now</button><button id="export">Export review log</button><p id="saved" role="status" aria-live="polite"></p></section></main>
<script>
const D=__DATA__, $=id=>document.getElementById(id);
const select=$('query'), video=$('video'), canvas=$('pitch'), ctx=canvas.getContext('2d'), slider=$('frame');
const key='blindspot-review-v3:'+D.experiment_id, outcomes=['unresolved','H','A','D','insufficient'];
let reviews={}, opened=performance.now(), inspectedFrame=0, generation=0, storageAvailable=true;
try{const stored=JSON.parse(localStorage.getItem(key)||'{}');if(stored&&typeof stored==='object'&&!Array.isArray(stored)){for(const [frame,r] of Object.entries(stored)){if(r&&typeof r==='object'&&Number(frame)===r.frame&&typeof r.notes==='string'&&outcomes.includes(r.state))reviews[frame]=r}}}catch(e){storageAvailable=false}
$('title').textContent=D.title;$('notice').textContent=D.notice;$('identity').textContent='Candidate / experiment: '+D.experiment_id;
const current=()=>D.queries[Number(select.value)];
const frameFromTime=(time,q)=>Math.max(q.clip_start,Math.min(q.clip_stop-1,q.clip_start+Math.floor(Math.max(0,time)*D.fps+1e-6)));
function render(frame){const q=current();if(!q)return;inspectedFrame=Math.max(q.clip_start,Math.min(q.clip_stop-1,Math.floor(frame)));slider.value=String(inspectedFrame);const index=inspectedFrame-q.clip_start,s=q.samples[Math.min(q.samples.length-1,Math.floor(index/D.sample_step))];ctx.fillStyle='#143d39';ctx.fillRect(0,0,632,408);ctx.strokeStyle='#a5ceba';ctx.strokeRect(1,1,630,406);ctx.beginPath();ctx.moveTo(316,0);ctx.lineTo(316,408);ctx.stroke();ctx.beginPath();ctx.ellipse(316,204,55,55,0,0,Math.PI*2);ctx.stroke();if(s){s.xy.forEach((p,i)=>{if(!p.every(Number.isFinite))return;ctx.fillStyle=D.teams[i]===0?'#51c5ff':'#c9a1ff';ctx.beginPath();ctx.arc(p[0]*632,p[1]*408,5,0,Math.PI*2);ctx.fill()});if(s.ball.length===2&&s.ball.every(Number.isFinite)){ctx.fillStyle='#ffe275';ctx.beginPath();ctx.arc(s.ball[0]*632,s.ball[1]*408,4,0,Math.PI*2);ctx.fill()}$('detail').textContent='Pitch sample '+s.frame+' · '+(inspectedFrame-s.frame)+' frame(s) before selected frame.'}const p=q.frame_support[index];$('prediction').textContent='Frame '+inspectedFrame+' · model '+q.frame_labels[index]+' · H/A/D support '+p.map(v=>v.toFixed(3)).join(' / ');}
function persist(){const q=current();if(!q)return;reviews[q.frame]={frame:q.frame,inspected_frame:inspectedFrame,state:$('state').value,notes:$('notes').value,interaction_seconds:+((performance.now()-opened)/1000).toFixed(2),saved_utc:new Date().toISOString(),experiment_id:D.experiment_id,scope:'Development review only; never a submission label'};try{localStorage.setItem(key,JSON.stringify(reviews));storageAvailable=true;$('saved').textContent='Saved for this candidate. Export to keep a portable copy.'}catch(e){storageAvailable=false;$('saved').textContent='Browser storage unavailable. Notes remain in memory; export before closing.'}}
function seek(frame){const q=current();if(!q)return;video.pause();render(frame);if(q.video_status==='verified_decoded')video.currentTime=(inspectedFrame-q.clip_start)/D.fps;}
function change(){const q=current();if(!q)return;generation++;const token=generation;video.pause();slider.min=q.clip_start;slider.max=q.clip_stop-1;render(q.clip_start);video.onloadedmetadata=()=>{if(token===generation){video.currentTime=0;render(q.clip_start)}};video.onloadeddata=()=>startFrameClock(token);if(q.video_status==='verified_decoded'){video.src=q.clip;$('videoStatus').textContent='Verified clip: '+q.encoded_frames+' frames at '+D.fps+' fps.'}else{video.removeAttribute('src');video.load();$('videoStatus').textContent='Video is not packaged. Frame controls still show model output and sampled pitch positions.'}const old=reviews[q.frame]||{};$('state').value=old.state||'unresolved';$('notes').value=old.notes||'';opened=performance.now();$('saved').textContent=storageAvailable?(old.notes!==undefined?'Restored notes for this candidate.':'No saved notes for this moment.'):'Storage unavailable or unreadable; export notes before closing.';$('reason').textContent='Score '+q.score.toFixed(3)+' · entropy '+q.entropy.toFixed(3)+' · model disagreement '+q.source_disagreement.toFixed(3)+' · ball '+(q.ball_missing?'missing':'observed')+'. Ambiguity does not establish an error.';$('prev').disabled=Number(select.value)===0;$('next').disabled=Number(select.value)===D.queries.length-1;}
D.queries.forEach((q,i)=>{const o=document.createElement('option');o.value=i;o.textContent=(i+1)+' · half '+q.half+' · frame '+q.frame;select.append(o)});
select.onchange=change;$('prev').onclick=()=>{select.value=String(Math.max(0,Number(select.value)-1));change()};$('next').onclick=()=>{select.value=String(Math.min(D.queries.length-1,Number(select.value)+1));change()};
slider.oninput=()=>seek(Number(slider.value));$('backFrame').onclick=()=>seek(inspectedFrame-1);$('forwardFrame').onclick=()=>seek(inspectedFrame+1);
video.ontimeupdate=()=>{const q=current();if(q&&q.video_status==='verified_decoded')render(frameFromTime(video.currentTime,q))};video.onseeked=video.ontimeupdate;video.onerror=()=>{$('videoStatus').textContent='Video could not be loaded. Use frame controls for model/pitch review; check the clip file.'};
function startFrameClock(token){if(typeof video.requestVideoFrameCallback!=='function')return;const tick=(now,metadata)=>{if(token!==generation)return;const q=current();if(q&&q.video_status==='verified_decoded')render(frameFromTime(metadata.mediaTime,q));video.requestVideoFrameCallback(tick)};video.requestVideoFrameCallback(tick)}
$('notes').oninput=persist;$('state').onchange=persist;$('save').onclick=persist;
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({schema_version:D.schema_version,experiment_id:D.experiment_id,scope:D.scope,reviews},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='CoreOrigin-review-'+D.experiment_id.slice(0,12)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),0)};
if(D.queries.length){select.value='0';change()}else{$('reason').textContent='No review moments were requested.';for(const id of ['query','prev','next','frame','backFrame','forwardFrame','state','notes','save'])$(id).disabled=true;}
</script></html>'''
